const LEGACY_TO_CORE={
 outline:['development','story_development'],
 writing:['writing','script_writing'],
 locked:['writing','script_locked'],
 shoot:['production','shoot_preparation'],
 filmed:['production','assets_pending'],
 post:['post','editing'],
 publish:['publishing','ready_to_publish']
};
const CORE_TO_LEGACY={
 idea:'outline',screening:'outline',story_development:'outline',
 script_writing:'writing',review_changes:'writing',script_locked:'locked',
 shoot_preparation:'shoot',shooting:'shoot',assets_pending:'filmed',
 ready_to_edit:'post',rough_cut:'post',revision:'post',final_cut:'post',
 ready_to_publish:'publish',published:'publish',reviewed:'publish'
};
const clean=(b={},raw={})=>{
 const stageWasChanged=Object.prototype.hasOwnProperty.call(raw,'productionStage');
 const substatusWasChanged=Object.prototype.hasOwnProperty.call(raw,'currentSubstatus');
 const legacyStage=String(
  stageWasChanged
   ? raw.productionStage
   : (substatusWasChanged ? (CORE_TO_LEGACY[raw.currentSubstatus]||b.productionStage) : (b.productionStage||'outline'))
 );
 const mapped=LEGACY_TO_CORE[legacyStage]||['development','story_development'];
 const currentStage=String(
  Object.prototype.hasOwnProperty.call(raw,'currentStage')
   ? raw.currentStage
   : (stageWasChanged ? mapped[0] : (b.currentStage||mapped[0]))
 );
 const currentSubstatus=String(
  substatusWasChanged
   ? raw.currentSubstatus
   : (stageWasChanged ? mapped[1] : (b.currentSubstatus||mapped[1]))
 );
 return {
  seasonNo:(+b.seasonNo===99?99:Math.max(1,+b.seasonNo||1)),
  titleZh:String(b.titleZh||''),titleEn:String(b.titleEn||''),
  categoryZh:String(b.categoryZh||''),categoryEn:String(b.categoryEn||''),
  summaryZh:String(b.summaryZh||''),summaryEn:String(b.summaryEn||''),
  scriptStatus:b.scriptStatus||'idea',
  productionStage:CORE_TO_LEGACY[currentSubstatus]||legacyStage,
  owner:String(b.owner||''),priority:b.priority||'medium',
  shootDate:String(b.shootDate||''),publishDate:String(b.publishDate||''),
  progress:Math.max(0,Math.min(100,+b.progress||0)),
  openIssues:String(b.openIssues??b.blocker??''),
  openIssuesEn:String(b.openIssuesEn||''),
  version:String(b.version||'v0.1'),scriptZh:String(b.scriptZh||''),
  scriptEn:String(b.scriptEn||''),culturePointZh:String(b.culturePointZh||''),
  culturePointEn:String(b.culturePointEn||''),views:Math.max(0,+b.views||0),
  retention30:+b.retention30||0,retention60:+b.retention60||0,
  avgWatchSeconds:+b.avgWatchSeconds||0,completionRate:+b.completionRate||0,
  nextEpisodeRate:+b.nextEpisodeRate||0,followersGained:Math.max(0,+b.followersGained||0),
  topComment:String(b.topComment||''),currentStage,currentSubstatus,
  reviewer:String(b.reviewer||''),nextAction:String(b.nextAction||''),
  blocker:String(b.blocker??b.openIssues??''),targetDate:String(b.targetDate||''),
  storageLink:String(b.storageLink||''),updatedBy:String(b.updatedBy||''),
  outlineCompletedAt:b.outlineCompletedAt||null,writingStartedAt:b.writingStartedAt||null,
  scriptLockedAt:b.scriptLockedAt||null,shootStartedAt:b.shootStartedAt||null,
  shootCompletedAt:b.shootCompletedAt||null,assetsArchivedAt:b.assetsArchivedAt||null,
  editCompletedAt:b.editCompletedAt||null,publishedAt:b.publishedAt||null,
  reviewedAt:b.reviewedAt||null
 };
};
const nowIso=()=>new Date().toISOString();
function applyMilestones(b,previous={}){
 const now=nowIso();
 const reached={
  outline:['writing','production','post','publishing'].includes(b.currentStage)||b.currentStage==='development'&&b.currentSubstatus==='story_development',
  writing:['writing','production','post','publishing'].includes(b.currentStage),
  locked:['production','post','publishing'].includes(b.currentStage)||b.currentSubstatus==='script_locked',
  shootStarted:['production','post','publishing'].includes(b.currentStage)&&b.currentSubstatus!=='shoot_preparation',
  shootCompleted:['post','publishing'].includes(b.currentStage)||['assets_pending','ready_to_edit'].includes(b.currentSubstatus),
  assets:['post','publishing'].includes(b.currentStage),
  edit:['publishing'].includes(b.currentStage)||['final_cut','ready_to_publish','published','reviewed'].includes(b.currentSubstatus),
  published:['published','reviewed'].includes(b.currentSubstatus)||Boolean(b.publishDate),
  reviewed:b.currentSubstatus==='reviewed'
 };
 return {
  ...b,
  outlineCompletedAt:b.outlineCompletedAt||previous.outlineCompletedAt||(reached.outline?now:null),
  writingStartedAt:b.writingStartedAt||previous.writingStartedAt||(reached.writing?now:null),
  scriptLockedAt:b.scriptLockedAt||previous.scriptLockedAt||(reached.locked?now:null),
  shootStartedAt:b.shootStartedAt||previous.shootStartedAt||(reached.shootStarted?now:null),
  shootCompletedAt:b.shootCompletedAt||previous.shootCompletedAt||(reached.shootCompleted?now:null),
  assetsArchivedAt:b.assetsArchivedAt||previous.assetsArchivedAt||(reached.assets?now:null),
  editCompletedAt:b.editCompletedAt||previous.editCompletedAt||(reached.edit?now:null),
  publishedAt:b.publishedAt||previous.publishedAt||(reached.published?(b.publishDate||now):null),
  reviewedAt:b.reviewedAt||previous.reviewedAt||(reached.reviewed?now:null)
 };
}
export async function onRequestPut({request,env}){
 if(!env.DB)return json({error:'D1 binding DB is not configured.'},503);
 try{
  await ensure(env);
  const raw=await request.json(),id=Number(raw.id),episodeNo=Number(raw.episodeNo);
  if(!id&&!episodeNo)return json({error:'Valid id or episodeNo required.'},400);
  const existing=id
   ?await env.DB.prepare(`SELECT ${cols} FROM episodes WHERE id=?`).bind(id).first()
   :await env.DB.prepare(`SELECT ${cols} FROM episodes WHERE season_no=? AND episode_no=?`).bind(+raw.seasonNo||1,episodeNo).first();
  if(!existing)return json({error:'Episode record not found; no changes were saved.'},404);
  const b=applyMilestones(clean({...existing,...raw},raw),existing);
  const values=[
   b.seasonNo,b.titleZh,b.titleEn,b.categoryZh,b.categoryEn,b.summaryZh,b.summaryEn,
   b.scriptStatus,b.productionStage,b.owner,b.priority,b.shootDate,b.publishDate,b.progress,
   b.openIssues,b.openIssuesEn,b.version,b.scriptZh,b.scriptEn,b.culturePointZh,b.culturePointEn,
   b.views,b.retention30,b.retention60,b.avgWatchSeconds,b.completionRate,b.nextEpisodeRate,
   b.followersGained,b.topComment,b.currentStage,b.currentSubstatus,b.reviewer,b.nextAction,
   b.blocker,b.targetDate,b.storageLink,b.updatedBy,b.outlineCompletedAt,b.writingStartedAt,
   b.scriptLockedAt,b.shootStartedAt,b.shootCompletedAt,b.assetsArchivedAt,b.editCompletedAt,
   b.publishedAt,b.reviewedAt
  ];
  const setSql=`season_no=?,title_zh=?,title_en=?,category_zh=?,category_en=?,summary_zh=?,summary_en=?,
   script_status=?,production_stage=?,owner=?,priority=?,shoot_date=?,publish_date=?,progress=?,
   open_issues=?,open_issues_en=?,version=?,script_zh=?,script_en=?,culture_point_zh=?,culture_point_en=?,
   views=?,retention_30=?,retention_60=?,avg_watch_seconds=?,completion_rate=?,next_episode_rate=?,
   followers_gained=?,top_comment=?,current_stage=?,current_substatus=?,reviewer=?,next_action=?,
   blocker=?,target_date=?,storage_link=?,updated_by=?,outline_completed_at=?,writing_started_at=?,
   script_locked_at=?,shoot_started_at=?,shoot_completed_at=?,assets_archived_at=?,edit_completed_at=?,
   published_at=?,reviewed_at=?,updated_at=CURRENT_TIMESTAMP`;
  const result=await env.DB.prepare(`UPDATE episodes SET ${setSql} WHERE id=?`).bind(...values,existing.id).run();
  if(Number(result?.meta?.changes||0)===0)return json({error:'No episode row was updated.'},409);
  const saved=await env.DB.prepare(`SELECT ${cols} FROM episodes WHERE id=?`).bind(existing.id).first();
  try{
   await logAudit(env.DB,'episode',existing.id,'update',{
    currentStage:b.currentStage,currentSubstatus:b.currentSubstatus,owner:b.owner,
    nextAction:b.nextAction,blocker:b.blocker,updatedBy:b.updatedBy
   });
  }catch(auditError){
   console.warn('Episode audit log failed after successful update:',auditError);
  }
  return json({episode:saved});
 }catch(e){return json({error:String(e?.message||e)},500)}
}
